//! End-to-end check against Apache Cassandra 5.0 (`CQLC_NODE`, default 127.0.0.1:9042): vector column and
//! `ANN OF` search with a SAI index, `similarity_cosine`, SAI range/equality/`CONTAINS` restrictions,
//! arithmetic and the 5.0 math/collection functions, all through code generated by `cqlc generate`.

#[rustfmt::skip]
mod queries;

use queries::*;
use scylla::client::session_builder::SessionBuilder;
use scylla::errors::TranslationError;
use scylla::policies::address_translator::{AddressTranslator, UntranslatedPeer};
use std::net::SocketAddr;
use std::sync::Arc;
use uuid::Uuid;

/// Pins every advertised node address to the one we dialled (Docker port mapping).
struct Pin(SocketAddr);

#[async_trait::async_trait]
impl AddressTranslator for Pin {
    async fn translate_address(
        &self,
        _: &UntranslatedPeer,
    ) -> Result<SocketAddr, TranslationError> {
        Ok(self.0)
    }
}

const SCHEMA: &str = include_str!("../schema/schema.cql");

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let node = std::env::var("CQLC_NODE").unwrap_or_else(|_| "127.0.0.1:9042".into());
    let addr: SocketAddr = std::net::ToSocketAddrs::to_socket_addrs(&node)?
        .next()
        .ok_or("bad CQLC_NODE")?;
    let session = SessionBuilder::new()
        .known_node_addr(addr)
        .address_translator(Arc::new(Pin(addr)))
        .build()
        .await?;
    session
        .query_unpaged("CREATE KEYSPACE IF NOT EXISTS cqlc_c5 WITH replication = {'class': 'SimpleStrategy', 'replication_factor': 1}", &[])
        .await?;
    session.use_keyspace("cqlc_c5", false).await?;
    for stmt in SCHEMA.split(';').map(str::trim).filter(|s| !s.is_empty()) {
        session.query_unpaged(stmt.to_string(), &[]).await?;
    }
    let q = Queries::new(Arc::new(session)).await?;

    #[allow(clippy::type_complexity)]
    let items: [(&str, &str, f64, i32, &[&str], [f32; 3]); 4] = [
        (
            "keyboard",
            "peripherals",
            49.0,
            10,
            &["usb", "mechanical"],
            [0.9, 0.1, 0.0],
        ),
        (
            "mouse",
            "peripherals",
            25.0,
            3,
            &["usb", "wireless"],
            [0.8, 0.2, 0.1],
        ),
        ("monitor", "displays", 199.0, 7, &["hdmi"], [0.1, 0.9, 0.2]),
        (
            "laptop",
            "computers",
            999.0,
            2,
            &["usb", "wifi"],
            [0.2, 0.3, 0.9],
        ),
    ];
    for (name, category, price, stock, tags, emb) in items {
        q.add_product(AddProductParams {
            id: Uuid::new_v4(),
            name: Some(name.into()),
            category: Some(category.into()),
            price: Some(price),
            stock: Some(stock),
            tags: Some(tags.iter().map(|t| t.to_string()).collect()),
            embedding: Some(emb.to_vec()),
            supplier_email: Some(format!("{name}@supplier.example")),
        })
        .await?;
    }
    // SAI indexes are built asynchronously; give them a moment to catch up.
    tokio::time::sleep(std::time::Duration::from_secs(3)).await;

    let probe = vec![0.85f32, 0.15, 0.05];
    let near = q
        .similar_products(SimilarProductsParams {
            score: probe.clone(),
            embedding_ann: probe,
        })
        .await?;
    println!(
        "nearest to [0.85, 0.15, 0.05]: {:?}",
        near.iter()
            .map(|r| (
                r.name.clone().unwrap_or_default(),
                r.score.map(|s| (s * 100.0).round() / 100.0)
            ))
            .collect::<Vec<_>>()
    );
    assert_eq!(near.len(), 3);
    assert!(
        matches!(near[0].name.as_deref(), Some("keyboard" | "mouse")),
        "peripherals are the closest"
    );

    let cheap = q
        .cheap_in_category(CheapInCategoryParams {
            category: "peripherals".into(),
            price: 30.0,
        })
        .await?;
    assert_eq!(cheap.len(), 1);
    assert_eq!(cheap[0].name.as_deref(), Some("mouse"));

    let usb = q.by_tag("usb".into()).await?;
    assert_eq!(usb.len(), 3);

    let priced = q.price_with_tax("peripherals".into()).await?;
    assert_eq!(priced.len(), 2);
    println!(
        "price with tax / abs(stock - 10) / tag count: {:?}",
        priced
            .iter()
            .map(|r| (r.gross, r.delta, r.tag_count))
            .collect::<Vec<_>>()
    );
    assert!(priced.iter().all(|r| r.tag_count == Some(2)));
    println!("ok: Cassandra 5.0 features exercised through generated code");
    Ok(())
}
